#include <stdio.h>

int main() {
    int myInteger = 42;
    char myCharacter = 'A';

    printf("Integer: %d\n", myInteger);
    // Output:
    // Integer: 42

    printf("Character: %c\n", myCharacter);
    // Output:
    // Character: A

    return 0;
}

.data
    // Format string for printing an integer
    format1:   .string  "Integer: %d\n"

    // Format string for printing a character
    format2:   .string  "Character: %c\n"

// Pseudo-ops and directives
main:
    // Program prologue
    ..
    // Loading the format string (format1) into x0 for printing an integer.
    ldr x0, =format1
    // passing the integer value to be printed to next argument register.
    // calling printf to print the integer value.
    ..

    // Loading the format string (format2) into x0 for printing a character.
    ldr x0, =format2
    // passing the character value to be printed to next argument register.
    // calling printf to print the character value.
    ..

    // program epilogue

// Pseudo-ops and directives
main:
    // Program prologue
    ..
    // Loading the format string (format1) into x0 for printing an integer.
    ldr x0, =format1
    // passing the integer value to be printed to next argument register.
    mov x1, 67
    // calling printf to print the integer value.
    ..

    // Loading the format string (format2) into x0 for printing a character.
    ldr x0, =format2
    // passing the character value to be printed to next argument register.
    mov x1, 'L'
    // calling printf to print the character value.
    ..

    // program epilogue

// Pseudo-ops and directives
main:
    // Program prologue
    ..
    // Loading the format string (format1) into x0 for printing an integer.
    ldr x0, =format1
    // passing the integer value to be printed to next argument register.
    mov x1, 67
    // calling printf to print the integer value.
    bl printf

    // Loading the format string (format2) into x0 for printing a character.
    ldr x0, =format2
    // passing the character value to be printed to next argument register.
    mov x1, 'L'
    // calling printf to print the character value.
    bl printf
    ..

    // program epilogue

body.starter:
.data
    // Format string for printing an integer
    format1:   .string  "Integer: %d\n"
    // Format string for printing a character
    format2:   .string  "Character: %c\n"

.text
    .balign 4
    .global main

main:
    // Program prologue
    stp     x29, x30, [sp, -16]!
    mov     x29, sp

    // Loading the format string (format1) into x0 for printing an integer.
    ldr x0, =format1
    // passing the integer value to be printed to next argument register.
    mov x1, 67
    // calling printf to print the integer value.
    bl printf

    // Loading the format string (format2) into x0 for printing a character.
    ldr x0, =format2
    // passing the character value to be printed to next argument register.
    mov x1, 'L'
    // calling printf to print the character value.
    bl printf

    // program epilogue
    mov     x0, 0
    ldp     x29, x30, [sp], 16
    ret
